                /// Details on when funds from charges are available, and when they are paid out to an external account.
                public struct Schedule: Codable, Hashable, Sendable {
                    /// The number of days charge funds are held before being paid out.
                    public var delayDays: DelayDays?
                    /// How frequently available funds are paid out.
                    public var interval: Interval?
                    /// The day of the month when available funds are paid out, specified as a number between 1--31.
                    public var monthlyAnchor: Int?
                    /// The days of the month when available funds are paid out, specified as an array of numbers between 1--31.
                    public var monthlyPayoutDays: [Int]?
                    /// The day of the week when available funds are paid out, specified as `monday`, `tuesday`, etc.
                    public var weeklyAnchor: WeeklyAnchor?
                    /// The days of the week when available funds are paid out, specified as an array, e.g., [`monday`, `tuesday`].
                    public var weeklyPayoutDays: [WeeklyPayoutDays]?

                    private enum CodingKeys: String, CodingKey {
                        case delayDays
                        case interval
                        case monthlyAnchor
                        case monthlyPayoutDays
                        case weeklyAnchor
                        case weeklyPayoutDays
                    }

                    public init(
                        delayDays: DelayDays? = nil,
                        interval: Interval? = nil,
                        monthlyAnchor: Int? = nil,
                        monthlyPayoutDays: [Int]? = nil,
                        weeklyAnchor: WeeklyAnchor? = nil,
                        weeklyPayoutDays: [WeeklyPayoutDays]? = nil
                    ) {
                        self.delayDays = delayDays
                        self.interval = interval
                        self.monthlyAnchor = monthlyAnchor
                        self.monthlyPayoutDays = monthlyPayoutDays
                        self.weeklyAnchor = weeklyAnchor
                        self.weeklyPayoutDays = weeklyPayoutDays
                    }

                    public enum Interval: String, Codable, Hashable, Sendable {
                        case daily
                        case manual
                        case monthly
                        case weekly
                    }

                    public enum WeeklyAnchor: String, Codable, Hashable, Sendable {
                        case friday
                        case monday
                        case saturday
                        case sunday
                        case thursday
                        case tuesday
                        case wednesday
                    }

                    public enum WeeklyPayoutDays: String, Codable, Hashable, Sendable {
                        case friday
                        case monday
                        case thursday
                        case tuesday
                        case wednesday
                    }

                    /// The number of days charge funds are held before being paid out.
                    public enum DelayDays: Codable, Hashable, Sendable {
                        case value(Int)
                        case minimum

                        public init(from decoder: any Decoder) throws {
                            let container = try decoder.singleValueContainer()
                            if let value = try? container.decode(Int.self) { self = .value(value); return }
                            switch try container.decode(String.self) {
                            case "minimum": self = .minimum
                            case let other: throw DecodingError.dataCorruptedError(in: container, debugDescription: "unknown keyword \(other)")
                            }
                        }

                        public func encode(to encoder: any Encoder) throws {
                            var container = encoder.singleValueContainer()
                            switch self {
                            case .value(let value): try container.encode(value)
                            case .minimum: try container.encode("minimum")
                            }
                        }
                    }
                }
            }

